package bo.com.ganadero.sanidad.api;
import bo.com.ganadero.sanidad.application.CrearTratamientoCommand;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.math.BigDecimal;import java.time.Instant;import java.util.*;
public record CrearTratamientoRequest(UUID casoClinicoId,@NotNull UUID animalId,@NotNull Instant fechaInicio,@NotNull Instant fechaFinEstimada,String diagnostico,UUID veterinarioId,String observaciones,@NotEmpty List<@Valid Detalle> detalles){public record Detalle(UUID productoId,UUID loteProductoId,@NotNull @DecimalMin("0.001") BigDecimal dosis,@NotBlank String unidadDosis,@NotNull @Min(1) Integer frecuenciaHoras,@NotNull @Min(1) Integer duracionDias,String viaAdministracion,@Min(0) Integer retiroCarneDias,@Min(0) Integer retiroLecheDias){}public CrearTratamientoCommand command(){return new CrearTratamientoCommand(casoClinicoId,animalId,fechaInicio,fechaFinEstimada,diagnostico,veterinarioId,observaciones,detalles.stream().map(d->new CrearTratamientoCommand.Detalle(d.productoId,d.loteProductoId,d.dosis,d.unidadDosis,d.frecuenciaHoras,d.duracionDias,d.viaAdministracion,d.retiroCarneDias,d.retiroLecheDias)).toList());}}
